import z3
solver = z3.Solver()
X = [z3.Int(f'x_{i}') for i in range(15)]
for x in X:
    solver.add(x >= 0, x < 15)
solver.add(z3.Distinct(X))

for d in range(1, 15):
    diffs = []
    for i in range(15 - d):
        diffs.append(X[i+d] - X[i])
    solver.add(z3.Distinct(diffs))

if solver.check() == z3.sat:
    m = solver.model()
    res = [m.evaluate(X[i]).as_long() for i in range(15)]
    print(res)
else:
    print("UNSAT")

